CREATE DATABASE IF NOT EXISTS libman8 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE libman8;
CREATE TABLE IF NOT EXISTS tblUser (
id INT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(80) UNIQUE NULL, passwordHash VARCHAR(100) NULL, fullName VARCHAR(150) NOT NULL, dateOfBirth DATE NOT NULL, address VARCHAR(255) NULL, email VARCHAR(150) NOT NULL UNIQUE, phone VARCHAR(20) NOT NULL, note VARCHAR(500) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tblReader (
userId INT PRIMARY KEY, studentCode VARCHAR(30) NOT NULL UNIQUE, academicYear VARCHAR(30) NULL, FOREIGN KEY(userId) REFERENCES tblUser(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tblStaff (
userId INT PRIMARY KEY, staffCode VARCHAR(30) NOT NULL UNIQUE, position VARCHAR(30) NOT NULL, FOREIGN KEY(userId) REFERENCES tblUser(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tblReaderCard (
id INT PRIMARY KEY AUTO_INCREMENT, cardCode VARCHAR(50) NOT NULL UNIQUE, readerId INT NOT NULL UNIQUE, issueDate DATE NOT NULL, expiryDate DATE NOT NULL, status VARCHAR(20) NOT NULL, FOREIGN KEY(readerId) REFERENCES tblReader(userId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tblDocument (
id INT PRIMARY KEY AUTO_INCREMENT, documentCode VARCHAR(40) NOT NULL UNIQUE, title VARCHAR(200) NOT NULL, documentType VARCHAR(50) NOT NULL, author VARCHAR(150) NOT NULL, publisher VARCHAR(150) NOT NULL, publicationYear INT NOT NULL, description VARCHAR(1000)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tblSupplier (
id INT PRIMARY KEY AUTO_INCREMENT, supplierCode VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, address VARCHAR(255), email VARCHAR(150), phone VARCHAR(20)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tblImportReceipt (
id INT PRIMARY KEY AUTO_INCREMENT, receiptCode VARCHAR(50) NOT NULL UNIQUE, importDate DATE NOT NULL, supplierId INT NOT NULL, staffId INT NOT NULL, FOREIGN KEY(supplierId) REFERENCES tblSupplier(id), FOREIGN KEY(staffId) REFERENCES tblStaff(userId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tblImportDetail (
id INT PRIMARY KEY AUTO_INCREMENT, importReceiptId INT NOT NULL, documentId INT NOT NULL, quantity INT NOT NULL CHECK(quantity>0), unitPrice DECIMAL(15,2) NOT NULL CHECK(unitPrice>=0), FOREIGN KEY(importReceiptId) REFERENCES tblImportReceipt(id), FOREIGN KEY(documentId) REFERENCES tblDocument(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tblDocumentCopy (
id INT PRIMARY KEY AUTO_INCREMENT, copyCode VARCHAR(50) NOT NULL UNIQUE, documentId INT NOT NULL, importDetailId INT NOT NULL, `condition` VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, FOREIGN KEY(documentId) REFERENCES tblDocument(id), FOREIGN KEY(importDetailId) REFERENCES tblImportDetail(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tblLoanSlip (
id INT PRIMARY KEY AUTO_INCREMENT, loanCode VARCHAR(50) NOT NULL UNIQUE, loanDate DATETIME NOT NULL, cardId INT NOT NULL, staffId INT NOT NULL, FOREIGN KEY(cardId) REFERENCES tblReaderCard(id), FOREIGN KEY(staffId) REFERENCES tblStaff(userId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tblLoanDetail (
id INT PRIMARY KEY AUTO_INCREMENT, loanSlipId INT NOT NULL, copyId INT NOT NULL, dueDate DATE NOT NULL, status VARCHAR(20) NOT NULL, FOREIGN KEY(loanSlipId) REFERENCES tblLoanSlip(id), FOREIGN KEY(copyId) REFERENCES tblDocumentCopy(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tblReturnSlip (
id INT PRIMARY KEY AUTO_INCREMENT, returnCode VARCHAR(50) NOT NULL UNIQUE, returnDate DATETIME NOT NULL, cardId INT NOT NULL, staffId INT NOT NULL, FOREIGN KEY(cardId) REFERENCES tblReaderCard(id), FOREIGN KEY(staffId) REFERENCES tblStaff(userId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tblReturnDetail (
id INT PRIMARY KEY AUTO_INCREMENT, returnSlipId INT NOT NULL, loanDetailId INT NOT NULL UNIQUE, returnCondition VARCHAR(20) NOT NULL, dailyLateFee DECIMAL(15,2) NOT NULL CHECK(dailyLateFee>=0), damageFine DECIMAL(15,2) NOT NULL CHECK(damageFine>=0), note VARCHAR(500), FOREIGN KEY(returnSlipId) REFERENCES tblReturnSlip(id), FOREIGN KEY(loanDetailId) REFERENCES tblLoanDetail(id), CHECK(returnCondition IN ('GOOD','DAMAGED')), CHECK(returnCondition<>'GOOD' OR damageFine=0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tblFineInvoice (
id INT PRIMARY KEY AUTO_INCREMENT, invoiceCode VARCHAR(50) NOT NULL UNIQUE, returnSlipId INT NOT NULL UNIQUE, paymentDate DATETIME NOT NULL, paymentMethod VARCHAR(20) NOT NULL, FOREIGN KEY(returnSlipId) REFERENCES tblReturnSlip(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;